 .js .collection-density { display: none; }
}
/* Native radio swatches preserve the original selected-color button treatment. */
.swatch-options { border: 0; margin: 0 0 1rem; padding: 0; min-width: 0; }
.swatch-options .color-swatch-item { position: relative; min-height: 44px; min-width: 44px; }
.color-swatch-item:has(input:focus-visible) { outline: 2px solid var(--color-ink); outline-offset: 3px; }
.color-swatch-item:has(input:disabled) { opacity: .45; cursor: default; }
.color-swatch-circle { display: grid; place-items: center; overflow: hidden; font-size: 11px; }
.color-swatch-circle img { width: 100%; height: 100%; object-fit: cover; }
.swatch-options--card .color-swatch-group { gap: 0; }
.swatch-options--card .color-swatch-item--color { padding: 0; justify-content: center; border-color: transparent; border-radius: 50%; background: transparent; box-shadow: none; }
.swatch-options--card .color-swatch-item--color:has(input:checked) { border-color: var(--color-ink); }
.swatch-options--card .color-swatch-circle { width: 18px; height: 18px; }
.product-card form .swatch-options { margin-bottom: .5rem; }
.reviews-summary { display: grid; grid-template-columns: minmax(180px, .65fr) minmax(0, 1fr); gap: 3rem; border-bottom: 1px solid var(--color-border); padding-bottom: 2rem; }
.reviews-average { font-size: 3rem; margin-bottom: .5rem; }
.reviews-average span { font-size: 1.25rem; }
.reviews-rating-row { width: 100%; display: grid; grid-template-columns: 44px minmax(0, 1fr) 32px; align-items: center; gap: 1rem; min-height: 44px; background: transparent; border: 0; padding: 0 .5rem; color: var(--color-ink); cursor: pointer; font: inherit; }
.reviews-rating-row[aria-pressed="true"] { outline: 1px solid var(--color-ink); background: var(--color-surface); }
.reviews-rating-row:disabled { cursor: default; }
.reviews-rating-track { display: block; height: 6px; background: var(--color-border); }
.reviews-rating-track > span { display: block; height: 100%; background: var(--color-ink); }
.reviews-controls { display: flex; flex-wrap: wrap; gap: 1rem 2rem; align-items: flex-end; margin-block: 2rem; }
.reviews-controls[hidden] { display: none; }
.reviews-controls select { min-width: 170px; }
.reviews-list .review-card { border: 0; border-bottom: 1px solid var(--color-border); padding-inline: 0; }
.reviews-list .review-card[hidden] { display: none; }
.review-star { color: var(--color-border); }
.review-star.is-active { color: var(--color-ink); }
.reviews-empty { padding-block: 2rem; }
.comparison-table-wrap { max-width: 100%; }
.comparison-table { min-width: 600px; }
@media (max-width: 749px) { .reviews-summary { grid-template-columns: 1fr; gap: 1.5rem; }.reviews-controls > div { flex: 1; }.reviews-controls select { width: 100%; } }

/* Balanced footer columns with one copy of each destination. */
.site-footer__grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1.8fr) minmax(0, 1.2fr); gap: clamp(2rem, 4vw, 4rem); }
.site-footer__brand-title { display: inline-block; }
