}

/* --------------------------------------------------------------------------
   Cart Drawer (Slide-out)
   -------------------------------------------------------------------------- */
.cart-drawer {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 200;
  pointer-events: none;
}

