/* Store extensions keep the original design system. */
.category-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 2rem; }
.category-tile { display: block; min-width: 0; }
.category-tile img, .category-tile svg { width: 100%; height: auto; aspect-ratio: 3/2; object-fit: cover; background: var(--color-surface); }
.category-tile h2, .category-tile h3 { font-size: 1.75rem; margin-block: 1rem; }
.collection-row-header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.shop-look__image { position: relative; }
.shop-look__image img { width: 100%; height: auto; }
.shop-look__pin { position: absolute; transform: translate(-50%, -50%); display: grid; place-items: center; width: 44px; height: 44px; border: 1px solid var(--color-ink); background: var(--color-bg); color: var(--color-ink); border-radius: 50%; }
.shop-look__products { display: flex; gap: 1rem; flex-wrap: wrap; }
.benefits-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 2rem; }
.benefits-grid h2 { font-size: 1.75rem; }
.footer-menu, .footer-menu ul { padding: 0; list-style: none; }
.footer-menu > li { margin-bottom: 1rem; }
.footer-menu ul { padding-left: .75rem; }
.site-footer__link { display: inline-flex; align-items: center; min-height: 44px; }
.footer-newsletter-fields { display: flex; gap: .5rem; margin-top: 1rem; flex-wrap: wrap; }
.footer-newsletter-fields input { min-width: 0; }
.product-enhancement-only { display: none; }
.product-enhanced .product-enhancement-only { display: block; }
.product-enhanced .product-native-variant { display: none; }
.product-buy-box > div, .product-buy-box .form-label { margin-bottom: 1rem; }
.product-buy-box .form-label { display: block; margin-top: 1rem; }
.product-gallery__image-container { position: relative; }
.product-zoom-link { position: absolute; right: 1rem; bottom: 1rem; padding-inline: .75rem; background: var(--color-bg); color: var(--color-ink); }
.product-gallery__thumb { min-width: 60px; min-height: 60px; }
.product-zoom-dialog img { display: block; max-height: 75dvh; max-width: 100%; width: auto; margin-inline: auto; }
.product-buy-box { top: 9rem; }
.quantity__button, .cart-item__stepper-btn, .cart-item__remove-btn, .cart-drawer__close-btn { min-height: 44px; min-width: 44px; }
.cart-drawer__body { min-height: 0; }
.cart-item__actions { flex-wrap: wrap; }
.cart-item__details { min-width: 0; }
.cart-item__title { overflow-wrap: anywhere; }
