  display: flex;
  gap: 1.25rem;
  padding: 1.25rem 0;
  border-bottom: 1px solid rgba(217, 208, 195, 0.6);
}

.cart-item:first-of-type {
  padding-top: 0;
}

.cart-item:last-of-type {
  border-bottom: none;
}

.cart-item__media {
  width: 72px;
  height: 90px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: var(--color-surface);
  flex-shrink: 0;
}

.cart-item__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cart-item__placeholder-thumb {
  width: 100%;
  height: 100%;
  background-color: var(--color-surface);
}

.cart-item__details {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.cart-item__header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 0.5rem;
