  .header-enhanced .header-mobile-fallback { display: none; }
  [data-header-section].header-enhanced .mobile-menu-toggle { display: flex !important; }
  .search-page-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 2rem 1rem; }
}
@media (max-width: 480px) {
