.contact-fields, .main-cart__footer-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; }
@media (max-width: 989px) {
 .category-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 2rem 1rem; }
 .product-spotlight__grid { grid-template-columns: 1fr; gap: 2rem; }
