/* A single balanced row keeps the wordmark at the true center. */
[data-header-section] .site-header__inner { grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); }
[data-header-section] .site-header__nav { padding: 0; justify-content: flex-start; }
.header-menu--desktop { justify-content: flex-start; flex-wrap: nowrap; gap: clamp(.75rem, 1.5vw, 1.5rem); }
.header-menu--desktop .site-header__nav-link { white-space: nowrap; font-size: .6875rem; letter-spacing: .08em; }
