}

/* --------------------------------------------------------------------------
   Section: FAQ
   -------------------------------------------------------------------------- */
.container--narrow {
  max-width: 800px;
}

/* --------------------------------------------------------------------------
   Section: Brand Story
   -------------------------------------------------------------------------- */
.brand-story__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(2.5rem, 6vw, 6rem);
  align-items: center;
}

.brand-story__media {
  aspect-ratio: 4/5;
  background-color: var(--color-surface);
  overflow: hidden;
}

.brand-story__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.brand-story__placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
}

.brand-story__heading {
  font-size: var(--font-h2);
  margin-top: 0.5rem;
  margin-bottom: 1.5rem;
}

.brand-story__body p {
  margin-bottom: 1.25rem;
}

.brand-story__signoff {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: var(--border-hairline);
}

@media (max-width: 800px) {
  .brand-story__grid {
    grid-template-columns: 1fr;
  }
}

/* --------------------------------------------------------------------------
   Section: Newsletter
   -------------------------------------------------------------------------- */
.newsletter-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  padding: clamp(2.5rem, 6vw, 4.5rem) clamp(1.5rem, 4vw, 3rem);
}

.newsletter-form__fields {
  display: flex;
  gap: 0.5rem;
  max-width: 480px;
  margin: 0 auto;
}

.newsletter-form__input {
  background-color: var(--color-bg);
}

@media (max-width: 600px) {
  .newsletter-form__fields {
    flex-direction: column;
  }
}

/* --------------------------------------------------------------------------
   Sticky Add-to-Cart Bar
   -------------------------------------------------------------------------- */
.sticky-cart-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background-color: var(--color-bg);
  border-top: var(--border-hairline);
  box-shadow: 0 -4px 16px rgba(0, 0, 0, 0.04);
  z-index: 80;
  transform: translateY(100%);
  transition: transform var(--transition-smooth);
}

.sticky-cart-bar.is-visible {
  transform: translateY(0);
}

.sticky-cart-bar__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
  gap: 1.5rem;
}

.sticky-cart-bar__product-info {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.sticky-cart-bar__thumb {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: var(--color-surface);
  flex-shrink: 0;
}

.sticky-cart-bar__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sticky-cart-bar__placeholder-thumb {
  width: 100%;
  height: 100%;
  background-color: var(--color-surface);
}

.sticky-cart-bar__title {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-ink);
  line-height: 1.2;
}

.sticky-cart-bar__sub {
  font-size: 0.8125rem;
  color: var(--color-muted);
  display: flex;
  gap: 0.375rem;
  align-items: center;
}

.sticky-cart-bar__btn {
  min-height: 44px;
  padding: 0.5rem 1.75rem;
  font-size: 0.75rem;
}

@media (max-width: 600px) {
  .sticky-cart-bar__title {
    display: none;
  }
}

/* --------------------------------------------------------------------------
   Custom Liquid Section
   -------------------------------------------------------------------------- */
.custom-liquid-section {
  padding-top: var(--space-6);
  padding-bottom: var(--space-6);
}

/* --------------------------------------------------------------------------
   Free Shipping Progress Bar
   -------------------------------------------------------------------------- */
.free-shipping-bar {
  width: 100%;
}

.free-shipping-bar__message {
  font-size: 0.8125rem;
  text-align: center;
  margin-bottom: 0.5rem;
  color: var(--color-ink);
}

.free-shipping-bar__progress-track {
  width: 100%;
  height: 4px;
  background-color: var(--color-border);
  border-radius: 2px;
  overflow: hidden;
}

.free-shipping-bar__progress-fill {
  height: 100%;
  background-color: var(--color-accent);
  transition: width 300ms ease;
}

/* --------------------------------------------------------------------------
   Cart Drawer (Slide-out)
   -------------------------------------------------------------------------- */
.cart-drawer {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 200;
  pointer-events: none;
}

.cart-drawer.is-open {
  pointer-events: auto;
}

.cart-drawer__backdrop {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(27, 26, 24, 0.45);
  opacity: 0;
  transition: opacity 250ms ease;
}

.cart-drawer.is-open .cart-drawer__backdrop {
  opacity: 1;
}

.cart-drawer__panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 100%;
  max-width: 440px;
  height: 100%;
  background-color: var(--color-bg);
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.06);
}

.cart-drawer.is-open .cart-drawer__panel {
  transform: translateX(0);
}

.cart-drawer__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 2rem;
  border-bottom: var(--border-hairline);
}

.cart-drawer__title-wrap {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.cart-drawer__title {
  font-size: 1.5rem;
  letter-spacing: 0.02em;
}

.cart-drawer__count-badge {
  font-size: 0.875rem;
  color: var(--color-muted);
}

.cart-drawer__close-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  color: var(--color-ink);
  cursor: pointer;
}

.cart-drawer__shipping-banner {
  padding: 1rem 2rem;
  background-color: var(--color-surface);
  border-bottom: var(--border-hairline);
}

.cart-drawer__body {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem 2rem;
}

.cart-drawer__empty {
  padding: 3rem 0;
}

.cart-drawer__footer {
  padding: 1.5rem 2rem;
  border-top: var(--border-hairline);
  background-color: var(--color-surface);
}

.cart-drawer__subtotal-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.cart-drawer__tax-note {
  font-size: 0.75rem;
  margin-bottom: 1.25rem;
}

.cart-drawer__note-accordion {
  margin-bottom: 1rem;
  border-bottom: 1px solid rgba(217, 208, 195, 0.6);
  padding-bottom: 0.75rem;
}

.cart-drawer__note-summary {
  font-size: 0.8125rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-muted);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  list-style: none;
}

.cart-drawer__note-summary::-webkit-details-marker {
  display: none;
}

.cart-drawer__note-content {
  padding-top: 0.75rem;
}

.cart-drawer__note-input {
  font-size: 0.8125rem;
  background-color: var(--color-bg);
}

/* --------------------------------------------------------------------------
   Cart Items (Shared between drawer and page)
   -------------------------------------------------------------------------- */
.cart-item {
  display: flex;
  gap: 1.25rem;
  padding: 1.25rem 0;
  border-bottom: 1px solid rgba(217, 208, 195, 0.6);
}

.cart-item:first-of-type {
  padding-top: 0;
}

.cart-item:last-of-type {
  border-bottom: none;
}

.cart-item__media {
  width: 72px;
  height: 90px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: var(--color-surface);
  flex-shrink: 0;
}

.cart-item__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cart-item__placeholder-thumb {
  width: 100%;
  height: 100%;
  background-color: var(--color-surface);
}

.cart-item__details {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.cart-item__header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 0.5rem;
}

.cart-item__title {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-ink);
  line-height: 1.3;
}

.cart-item__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 0.75rem;
}

.cart-item__stepper {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: var(--color-bg);
}

.cart-item__stepper-btn {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  color: var(--color-ink);
  cursor: pointer;
  transition: opacity var(--transition-fast);
}

.cart-item__stepper-btn:hover {
  opacity: 0.6;
}

.cart-item__qty-display {
  padding: 0 0.5rem;
  font-size: 0.8125rem;
  font-weight: 500;
}

.cart-item__remove-btn {
  font-size: 0.75rem;
  text-decoration: underline;
  text-underline-offset: 2px;
  color: var(--color-muted);
  cursor: pointer;
  transition: color var(--transition-fast);
}

.cart-item__remove-btn:hover {
  color: var(--color-ink);
}

/* Header and search extend the existing palette, type and buttons. */
