/* Shared section lifecycle and scroll animation, including editor re-renders. */
(() => {
  'use strict';
  const observers = new WeakMap();
  const theme = window.AtelierTheme = window.AtelierTheme || {};
  theme.syncScrollLock = () => {
    document.body.style.overflow = document.querySelector('dialog[open], [data-cart-drawer].is-open') ? 'hidden' : '';
  };
  function init(scope = document) {
    observers.get(scope)?.disconnect();
    const nodes = [...scope.querySelectorAll('.fade-up')];
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      nodes.forEach(node => node.classList.add('is-visible'));
      return;
    }
    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); }
      });
    }, { rootMargin: '0px 0px -40px 0px', threshold: .1 });
    observers.set(scope, observer);
    nodes.forEach(node => observer.observe(node));
  }
  const selectedDisclosures = new WeakMap();
  const selectedVisibility = new WeakMap();
  function reveal(event) {
    const root = event.target;
    root.closest?.('.fade-up')?.classList.add('is-visible');
    root.querySelectorAll('.fade-up').forEach(node => node.classList.add('is-visible'));
    if (root.matches?.('.fade-up')) root.classList.add('is-visible');
    if (event.type === 'shopify:block:select') {
      selectedVisibility.set(root, root.hidden);
      root.hidden = false;
      const details = root.matches?.('details') ? root : root.querySelector('details');
      if (details) { selectedDisclosures.set(root, details.open); details.open = true; }
    }
  }
  document.addEventListener('DOMContentLoaded', () => init());
  document.addEventListener('shopify:section:load', event => init(event.target));
  document.addEventListener('shopify:section:unload', event => {
    observers.get(event.target)?.disconnect();
    event.target.querySelectorAll('.fade-up').forEach(node => observers.get(document)?.unobserve(node));
    event.target.querySelectorAll('dialog[open]').forEach(dialog => dialog.close());
    if (event.target.querySelector('[data-cart-drawer].is-open')) window.dispatchEvent(new CustomEvent('cart:close'));
    theme.syncScrollLock();
  });
  document.addEventListener('shopify:section:select', reveal);
  document.addEventListener('shopify:block:select', reveal);
  document.addEventListener('shopify:block:deselect', event => {
    const root = event.target;
    if (selectedVisibility.has(root)) { root.hidden = selectedVisibility.get(root); selectedVisibility.delete(root); }
    const details = root.matches?.('details') ? root : root.querySelector('details');
    if (details && selectedDisclosures.has(root)) { details.open = selectedDisclosures.get(root); selectedDisclosures.delete(root); }
  });
  document.addEventListener('shopify:section:deselect', () => theme.syncScrollLock());
})();

/* Product options, native gallery controls, recommendations and bounded recent history. */
(() => {
  'use strict';
  const initialized = new WeakSet();
  const controllers = new WeakMap();
  function begin(root) {
    if (initialized.has(root)) return null;
    initialized.add(root);
    const controller = new AbortController();
    controllers.set(root, controller);
    return controller;
  }
  const historyKey = 'atelier-recent-products';
  function showMedia(root, id) {
    const slides = [...root.querySelectorAll('[data-product-media]')];
    const selected = slides.find(slide => slide.dataset.mediaId === String(id) || slide.dataset.imageId === String(id)) || slides[0];
    slides.forEach(slide => {
      slide.classList.toggle('is-active', slide === selected);
      if (slide !== selected) slide.querySelectorAll('video').forEach(video => video.pause());
    });
    root.querySelectorAll('[data-media-select]').forEach(link => {
      const active = link.dataset.mediaSelect === selected?.dataset.mediaId;
      link.classList.toggle('is-active', active);
      link.setAttribute('aria-current', String(active));
    });
  }
  function initProduct(root) {
    const controller = begin(root);
    if (!controller) return;
    const { signal } = controller;
    const variants = JSON.parse(root.querySelector('[data-product-variants]').dataset.variants);
    const selectors = [...root.querySelectorAll('[data-product-option]')];
    const form = root.querySelector('[data-product-form]');
    const nativeVariant = root.querySelector('[data-product-variant-id]');
    // Keep the native variant form usable if merchant blocks omit the picker or buy button.
    if (form && nativeVariant && (selectors.length || variants.length === 1)) {
      root.classList.add('product-enhanced');
      const update = () => {
        const chosen = selectors.map(group => group.querySelector('input:checked')?.value);
        const variant = selectors.length ? variants.find(item => item.options.every((value, index) => value === chosen[index])) : variants[0];
        const button = form.querySelector('[data-product-submit]');
        nativeVariant.value = variant?.id || '';
        button.disabled = !variant?.available || form.dataset.adding === 'true';
        button.textContent = !variant ? 'Unavailable' : variant.available ? 'Add to bag' : 'Sold out';
        const price = root.querySelector('[data-product-price]');
        if (price) {
          price.replaceChildren();
          if (variant) {
            const amount = document.createElement('span');amount.textContent = variant.price;price.append(amount);
            if (variant.comparePrice) { const compare = document.createElement('s');compare.className = 'text-muted';compare.textContent = variant.comparePrice;price.append(' ', compare); }
          }
        }
        form.querySelector('[data-catalog-status]').textContent = variant ? '' : 'This combination is unavailable. Choose another option.';
        if (variant) {
          const url = new URL(location.href);url.searchParams.set('variant', variant.id);history.replaceState({}, '', url);
          showMedia(root, variant.imageId);
          if (variant.image && !root.querySelector(`[data-media-id="${variant.imageId}"], [data-image-id="${variant.imageId}"]`)) {
            const image = root.querySelector('[data-product-media].is-active img');
            if (image) { image.removeAttribute('srcset');image.src = variant.image;image.alt = variant.alt;const zoom = image.closest('[data-product-media]').querySelector('[data-product-zoom]');if (zoom) zoom.href = variant.image; }
          }
        }
      };
      selectors.forEach(select => select.addEventListener('change', update, { signal }));
      update();
    }
    root.querySelectorAll('[data-product-quantity]').forEach(button => button.addEventListener('click', () => {
      const input = root.querySelector('input[name="quantity"]');
      input.value = Math.max(1, Number(input.value || 1) + Number(button.dataset.productQuantity));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    }, { signal }));
    root.querySelectorAll('[data-media-select]').forEach(link => link.addEventListener('click', event => { event.preventDefault();showMedia(root, link.dataset.mediaSelect); }, { signal }));
    const dialog = root.querySelector('[data-product-zoom-dialog]');
    let trigger;
    root.querySelectorAll('[data-product-zoom]').forEach(link => link.addEventListener('click', event => {
      event.preventDefault();trigger = link;
      const image = document.createElement('img');image.src = link.href;image.alt = link.closest('[data-product-media]').querySelector('img')?.alt || '';
      dialog.querySelector('[data-product-zoom-content]').replaceChildren(image);dialog.showModal();document.body.style.overflow = 'hidden';
    }, { signal }));
    dialog?.querySelector('[data-product-zoom-close]').addEventListener('click', () => dialog.close(), { signal });
    dialog?.addEventListener('close', () => { window.AtelierTheme.syncScrollLock();if (trigger?.isConnected) trigger.focus(); }, { signal });
  }
  async function recommendations(root) {
    const controller = begin(root);
    if (!controller) return;
    const { signal } = controller;
    try {
      const url = new URL(root.dataset.url, location.origin);
      url.searchParams.set('section_id', root.dataset.sectionId);url.searchParams.set('product_id', root.dataset.productId);url.searchParams.set('intent', root.dataset.intent);url.searchParams.set('limit', root.dataset.limit);
      const response = await fetch(url, { signal });if (!response.ok) return;
      const html = new DOMParser().parseFromString(await response.text(), 'text/html');
      const content = html.querySelector('[data-recommendation-content]');
      if (!root.isConnected || !content?.querySelector('[data-product-card]')) return;
      root.querySelector('[data-recommendation-content]').replaceChildren(...content.childNodes);root.hidden = false;root.dispatchEvent(new CustomEvent('catalog:cards:load', { bubbles: true, detail: { root } }));
    } catch { /* Optional recommendations remain hidden on failure. */ }
  }
  async function recent(root) {
    const controller = begin(root);
    if (!controller) return;
    const { signal } = controller;
    try {
      const saved = JSON.parse(localStorage.getItem(historyKey) || '[]');
      if (!Array.isArray(saved)) return;
      const current = root.dataset.currentUrl;
      const urls = [...new Set(saved)].filter(value => {
        if (typeof value !== 'string' || value === current) return false;
        const url = new URL(value, location.origin);
        return url.origin === location.origin && /^\/(?:[a-z]{2}(?:-[a-z]{2})?\/)?products\/[a-z0-9-]+$/i.test(url.pathname) && !url.search && !url.hash;
      }).slice(0, Number(root.dataset.limit));
      const cards = await Promise.all(urls.map(async value => {
        try { const url = new URL(value, location.origin);url.searchParams.set('section_id', 'recent-product-card');const response = await fetch(url, { signal });if (!response.ok) return null;const html = new DOMParser().parseFromString(await response.text(), 'text/html');return html.querySelector('[data-recent-card]'); } catch { return null; }
      }));
      if (!root.isConnected) return;
      const available = cards.filter(Boolean);root.querySelector('[data-recent-products]').replaceChildren(...available);root.hidden = !available.length;root.dispatchEvent(new CustomEvent('catalog:cards:load', { bubbles: true, detail: { root } }));
    } catch { /* Storage can be blocked or malformed. */ }
  }
  function init(scope = document) {
    scope.querySelectorAll('[data-main-product]').forEach(initProduct);
    scope.querySelectorAll('[data-product-recommendations]').forEach(recommendations);
    scope.querySelectorAll('[data-recently-viewed]').forEach(recent);
    const current = scope.querySelector('[data-main-product]')?.dataset.productUrl;
    if (current) try { let stored;try { stored = JSON.parse(localStorage.getItem(historyKey) || '[]'); } catch { stored = []; }localStorage.setItem(historyKey, JSON.stringify([current, ...(Array.isArray(stored) ? stored : []).filter(value => typeof value === 'string' && value !== current)].slice(0, 8))); } catch { /* Optional history. */ }
  }
  document.addEventListener('DOMContentLoaded', () => init());
  document.addEventListener('shopify:section:load', event => init(event.target));
  document.addEventListener('shopify:section:unload', event => {
    event.target.querySelectorAll('[data-main-product], [data-product-recommendations], [data-recently-viewed]').forEach(root => {
      controllers.get(root)?.abort();
      controllers.delete(root);
      initialized.delete(root);
    });
  });
})();

/* Sorting and filtering use the same real records as the server-rendered summary. */
(() => {
  const initialized = new WeakSet();
  function init(scope = document) {
    scope.querySelectorAll('[data-reviews]').forEach(root => {
      if (initialized.has(root) || !root.querySelector('[data-review-list]')) return;
      initialized.add(root);
      const list = root.querySelector('[data-review-list]');
      const records = [...list.querySelectorAll('[data-review]')].map((node, index) => ({ node, index, rating: Number(node.dataset.rating), date: /^\d{4}-\d{2}-\d{2}$/.test(node.dataset.date) ? Date.parse(node.dataset.date) || 0 : 0 }));
      const rating = root.querySelector('[data-review-rating]');
      const sort = root.querySelector('[data-review-sort]');
      root.querySelector('[data-review-controls]').hidden = false;
      root.querySelectorAll('[data-review-stars]').forEach(button => { button.disabled = false; });
      function update() {
        const selected = rating.value;
        const sorted = [...records].sort((a, b) => {
          if (sort.value === 'highest') return b.rating - a.rating || b.date - a.date || a.index - b.index;
          if (sort.value === 'lowest') return a.rating - b.rating || b.date - a.date || a.index - b.index;
          return (sort.value === 'oldest' ? a.date - b.date : b.date - a.date) || a.index - b.index;
        });
        sorted.forEach(record => { record.node.hidden = selected !== 'all' && record.rating !== Number(selected);list.append(record.node); });
        const visible = sorted.filter(record => !record.node.hidden).length;
        root.querySelector('[data-review-count]').textContent = `${visible} of ${records.length} reviews`;
        root.querySelector('[data-review-empty]').hidden = visible > 0;
        root.querySelectorAll('[data-review-stars]').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.reviewStars === selected)));
      }
      rating.addEventListener('change', update);sort.addEventListener('change', update);
      root.querySelector('[data-review-clear]').addEventListener('click', () => { rating.value = 'all';update(); });
      root.querySelectorAll('[data-review-stars]').forEach(button => button.addEventListener('click', () => { rating.value = button.dataset.reviewStars;update(); }));
      update();
    });
  }
  document.addEventListener('DOMContentLoaded', () => init());
  document.addEventListener('shopify:section:load', event => init(event.target));
  document.addEventListener('shopify:section:unload', event => {
    event.target.querySelectorAll('[data-reviews]').forEach(root => initialized.delete(root));
  });
})();

/* Cart totals and lines are rendered by Shopify Liquid in the active currency. */
(() => {
  'use strict';
  let drawer;
  let returnFocus;
  let busy = false;
  const config = () => document.querySelector('[data-cart-drawer]');
  const error = message => { const status = config()?.querySelector('[data-cart-error]');if (status) status.textContent = message; };
  function open() {
    drawer = config();if (!drawer) return;
    if (!drawer.classList.contains('is-open') && !returnFocus) returnFocus = document.activeElement;
    drawer.classList.add('is-open');drawer.removeAttribute('inert');drawer.setAttribute('aria-hidden', 'false');document.body.style.overflow = 'hidden';
    drawer.querySelector('[data-cart-drawer-close]')?.focus();
  }
  function close() {
    drawer = config();if (!drawer) return;
    drawer.classList.remove('is-open');drawer.setAttribute('inert', '');drawer.setAttribute('aria-hidden', 'true');window.AtelierTheme.syncScrollLock();
    if (returnFocus?.isConnected) returnFocus.focus();returnFocus = null;
  }
  function replace(html) {
    const parsed = new DOMParser().parseFromString(html || '', 'text/html').querySelector('[data-cart-drawer]');
    if (!parsed) throw new Error('Your bag changed. Reload the page to see its current contents.');
    const existing = config();existing.replaceChildren(...parsed.childNodes);
    const count = existing.querySelector('[data-cart-drawer-count]')?.dataset.itemCount || '0';
    document.querySelectorAll('[data-cart-count]').forEach(badge => { badge.textContent = count;badge.closest('[data-cart-drawer-trigger]')?.setAttribute('aria-label', `Bag, ${count} items`); });
  }
  async function mutate(url, payload) {
    if (busy) return;
    busy = true;const previous = document.activeElement;const focusKey = previous?.dataset.key;const focusType = previous?.dataset.cartQuantityStep;
    const target = config();target.setAttribute('aria-busy', 'true');error('Updating your bag…');
    target.querySelectorAll('button, input, textarea').forEach(control => { control.disabled = true; });
    try {
      const response = await fetch(`${url}.js`, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify({ ...payload, sections: ['cart-drawer'], sections_url: location.pathname }) });
      const data = await response.json();if (!response.ok) throw new Error(data.description || 'Could not update your bag. Try again.');
      let html = data.sections?.['cart-drawer'];
      if (!html) { const sectionUrl = new URL(target.dataset.cartUrl, location.origin);sectionUrl.searchParams.set('sections', 'cart-drawer');const response = await fetch(sectionUrl);if (response.ok) html = (await response.json())['cart-drawer']; }
      replace(html);
      const next = [...target.querySelectorAll('[data-key]')].find(control => control.dataset.key === focusKey && (focusType ? control.dataset.cartQuantityStep === focusType : control.matches('[data-cart-quantity]')));
      (next || target.querySelector('[data-cart-drawer-close]'))?.focus();
    } catch (err) { error(err.message || 'Could not update your bag.'); }
    finally { busy = false;target.removeAttribute('aria-busy');target.querySelectorAll('button, input, textarea').forEach(control => { control.disabled = false; }); }
  }
  document.addEventListener('click', event => {
    if (event.target.closest('[data-cart-drawer-close], [data-cart-drawer-backdrop]')) { close();return; }
    const step = event.target.closest('[data-cart-quantity-step]');
    const remove = event.target.closest('[data-cart-remove]');
    if (!step && !remove) return;
    if (!event.target.closest('[data-cart-drawer]')) return;
    event.preventDefault();const input = step?.closest('[data-cart-stepper]').querySelector('input');
    const quantity = remove ? 0 : Math.max(0, Number(input.value) + Number(step.dataset.cartQuantityStep));
    mutate(config().dataset.changeUrl, { id: (step || remove).dataset.key, quantity });
  });
  document.addEventListener('change', event => {
    if (!event.target.closest('[data-cart-drawer]')) return;
    if (event.target.matches('[data-cart-quantity]')) {
      if (!event.target.checkValidity()) { event.target.reportValidity();return; }
      mutate(config().dataset.changeUrl, { id: event.target.dataset.key, quantity: Number(event.target.value) });
    }
    if (event.target.matches('[data-cart-note]')) mutate(config().dataset.updateUrl, { note: event.target.value });
  });
  document.addEventListener('shopify:section:select', event => { if (event.target.querySelector('[data-cart-drawer]')) open(); });
  document.addEventListener('shopify:section:deselect', event => { if (event.target.querySelector('[data-cart-drawer]')) close(); });
  window.addEventListener('cart:open', open);window.addEventListener('cart:close', close);
  window.addEventListener('cart:rendered', event => { returnFocus = event.detail?.trigger;open(); });
  window.addEventListener('keydown', event => {
    const target = config();if (!target?.classList.contains('is-open')) return;
    if (event.key === 'Escape') { close();return; }
    if (event.key !== 'Tab') return;
    const controls = [...target.querySelectorAll('a, button, input, textarea, select')].filter(control => !control.disabled && control.getClientRects().length);
    const first = controls[0];const last = controls.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault();last?.focus(); }
    if (!event.shiftKey && document.activeElement === last) { event.preventDefault();first?.focus(); }
  });
})();

/* Progressive catalog controls. Native forms and product links work without JS. */
(() => {
  'use strict';
  const initialized = new WeakSet();
  const collections = new WeakMap();
  const quickDialog = () => document.querySelector('[data-quick-view-dialog]');
  let quickRequest;
  let quickTrigger;

  function bindDialog(dialog) {
    if (!dialog || initialized.has(dialog)) return;
    initialized.add(dialog);
    dialog.addEventListener('click', (event) => {
      if (event.target.closest('[data-dialog-close]') || event.target === dialog) dialog.close();
    });
    dialog.addEventListener('close', () => {
      window.AtelierTheme.syncScrollLock();
      if (dialog.catalogReturnFocus?.getClientRects().length) dialog.catalogReturnFocus.focus();
      if (dialog === quickDialog()) {
        quickRequest?.abort();
        if (!document.querySelector('[data-cart-drawer].is-open')) quickTrigger?.focus();
      }
    });
  }

  function initCollections(root = document) {
    root.querySelectorAll('[data-collection-section]').forEach(section => {
      if (initialized.has(section)) return;
      initialized.add(section);
      section.classList.add('catalog-enhanced');
      const form = section.querySelector('[data-collection-filters]');
      const home = section.querySelector('[data-filter-home]');
      const dialog = section.querySelector('[data-filter-dialog]');
      const destination = section.querySelector('[data-filter-destination]');
      const openButton = section.querySelector('[data-filter-open]');
      const media = window.matchMedia('(max-width: 989px)');
      bindDialog(dialog);
      const moveFilters = () => {
        if (!section.isConnected) { media.removeEventListener('change', moveFilters); return; }
        if (dialog.open) dialog.close();
        (media.matches && openButton ? destination : home).append(form);
      };
      moveFilters();
      media.addEventListener('change', moveFilters);
      collections.set(section, () => { media.removeEventListener('change', moveFilters); if (dialog.open) dialog.close(); });
      openButton?.addEventListener('click', () => {
        dialog.catalogReturnFocus = openButton;
        dialog.showModal();
        document.body.style.overflow = 'hidden';
      });
      section.querySelector('[data-collection-sort]')?.addEventListener('change', () => form.requestSubmit());
      // Empty price fields should not create meaningless filter parameters.
      form.addEventListener('submit', () => {
        form.querySelectorAll('input[type="number"]').forEach(input => { if (!input.value) input.disabled = true; });
      });
      section.querySelectorAll('[data-grid-columns]').forEach(button => {
        button.addEventListener('click', () => {
          section.style.setProperty('--collection-columns', button.dataset.gridColumns);
          section.querySelectorAll('[data-grid-columns]').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
        });
      });
    });
  }

  function updateVariant(form) {
    const variants = JSON.parse(form.querySelector('[data-variant-data]').dataset.variants);
    const selected = Array.from(form.querySelectorAll('[data-variant-option]'), group => group.querySelector('input:checked')?.value);
    const variant = variants.find(item => item.options.every((value, index) => value === selected[index]));
    const button = form.querySelector('[data-variant-submit]');
    const hiddenId = form.querySelector('[name="id"]');
    button.disabled = !variant?.available;
    button.textContent = !variant ? 'Unavailable' : variant.available ? 'Add to bag' : 'Sold out';
    hiddenId.value = variant?.id || '';
    const product = form.closest('[data-quick-view-product]');
    const price = product.querySelector('[data-quick-view-price]');
    price.replaceChildren();
    if (variant) {
      const amount = document.createElement('span');
      amount.textContent = variant.price;
      price.append(amount);
      if (variant.comparePrice) {
        const comparison = document.createElement('s');
        comparison.className = 'text-muted';
        comparison.textContent = variant.comparePrice;
        price.append(' ', comparison);
      }
    }
    const image = product.querySelector('[data-quick-view-image]');
    if (image) {
      if (!image.dataset.originalSrc) {
        image.dataset.originalSrc = image.currentSrc || image.src;
        image.dataset.originalAlt = image.alt;
      }
      image.removeAttribute('srcset');
      image.src = variant?.image || image.dataset.originalSrc;
      image.alt = variant?.image ? variant.alt : image.dataset.originalAlt;
    }
    form.querySelector('[data-catalog-status]').textContent = variant ? '' : 'This combination is unavailable. Choose another option.';
  }

  function updateCard(form) {
    const data = form.querySelector('[data-product-variants]');
    if (!data) return;
    const variant = JSON.parse(data.dataset.variants).find(item => String(item.id) === String(new FormData(form).get('id')));
    if (!variant) return;
    const card = form.closest('[data-product-card]');
    const price = card.querySelector('[data-card-price]');
    price.replaceChildren();
    const amount = document.createElement('span');amount.textContent = variant.price;price.append(amount);
    if (variant.comparePrice) { const comparison = document.createElement('s');comparison.className = 'text-muted';comparison.textContent = variant.comparePrice;price.append(' ', comparison); }
    form.querySelector('button[type="submit"]').disabled = !variant.available || form.dataset.adding === 'true';
    card.querySelectorAll('.product-card__media, .product-card__title a').forEach(link => { const url = new URL(link.href);url.searchParams.set('variant', variant.id);link.href = url; });
    if (variant.image) { const image = card.querySelector('.product-card__image');if (image) { image.removeAttribute('srcset');image.src = variant.image;image.alt = variant.alt; } }
  }

  async function openQuickView(link) {
    const dialog = quickDialog();
    if (!dialog) { window.location.assign(link.href); return; }
    quickRequest?.abort();
    quickRequest = new AbortController();
    const request = quickRequest;
    quickTrigger = link;
    bindDialog(dialog);
    const content = dialog.querySelector('[data-quick-view-content]');
    content.setAttribute('role', 'status');
    content.setAttribute('aria-live', 'polite');
    content.textContent = 'Loading product…';
    dialog.setAttribute('aria-label', 'Choose product options');
    dialog.removeAttribute('aria-labelledby');
    dialog.showModal();
    document.body.style.overflow = 'hidden';
    try {
      const url = new URL(link.href);
      url.searchParams.set('section_id', 'quick-view');
      const response = await fetch(url, { signal: request.signal });
      if (!response.ok) throw new Error('Could not load product.');
      const html = await response.text();
      if (request.signal.aborted || !dialog.open) return;
      const documentFragment = new DOMParser().parseFromString(html, 'text/html');
      const product = documentFragment.querySelector('[data-quick-view-product]');
      if (!product) throw new Error('This product is unavailable.');
      content.removeAttribute('role');
      content.removeAttribute('aria-live');
      content.replaceChildren(product);
      dialog.setAttribute('aria-labelledby', product.querySelector('h2').id);
      const form = product.querySelector('[data-variant-form]');
      updateVariant(form);
      product.querySelector('input[type="radio"]:checked, button, a')?.focus();
    } catch (error) {
      if (error.name === 'AbortError') return;
      content.textContent = `${error.message} `;
      const fallback = document.createElement('a');
      fallback.className = 'btn btn--link';
      fallback.href = link.href;
      fallback.textContent = 'View product details';
      content.append(fallback);
    }
  }

  async function addToBag(form) {
    const button = form.querySelector('button[type="submit"]');
    const status = form.querySelector('[data-catalog-status]');
    if (button.disabled || form.dataset.adding === 'true') return;
    const settings = document.querySelector('[data-catalog-config]');
    const cartUrl = settings?.dataset.cartUrl;
    if (!cartUrl) { form.submit(); return; }
    const body = new FormData(form);
    body.set('sections', 'cart-drawer');
    body.set('sections_url', window.location.pathname);
    form.dataset.adding = 'true';
    const selectors = [...form.querySelectorAll('select, input[type="radio"]')].filter(control => !control.disabled);
    selectors.forEach(select => { select.disabled = true; });
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    status.textContent = 'Adding to bag…';
    let added = false;
    try {
      const response = await fetch(`${form.action}.js`, { method: 'POST', body, headers: { Accept: 'application/json' } });
      const result = await response.json();
      if (!response.ok) throw new Error(result.description || 'Could not add this item. Please try again.');
      added = true;
      if (settings.dataset.cartType === 'page') { window.location.assign(cartUrl); return; }
      const drawer = document.querySelector('[data-cart-drawer]');
      const rendered = new DOMParser().parseFromString(result.sections?.['cart-drawer'] || '', 'text/html').querySelector('[data-cart-drawer]');
      if (!drawer || !rendered) {
        status.replaceChildren('Added to your bag. ');
        const cartLink = document.createElement('a');
        cartLink.className = 'btn btn--link';
        cartLink.href = cartUrl;
        cartLink.textContent = 'View bag';
        status.append(cartLink);
        return;
      }
      const returnTrigger = quickDialog()?.open ? quickTrigger : form.querySelector('button');
      if (quickDialog()?.open) quickDialog().close();
      drawer.replaceChildren(...rendered.childNodes);
      const count = drawer.querySelector('[data-cart-drawer-count]')?.dataset.itemCount;
      document.querySelectorAll('[data-cart-count]').forEach(badge => { badge.textContent = count || '';badge.closest('[data-cart-drawer-trigger]')?.setAttribute('aria-label', `Bag, ${count} items`); });
      status.textContent = 'Added to your bag.';
      window.dispatchEvent(new CustomEvent('cart:rendered', { detail: { trigger: returnTrigger } }));
    } catch (error) {
      status.textContent = added ? 'Added to your bag. Open your bag to continue.' : error.message || 'Could not add this item. Please try again.';
    } finally {
      delete form.dataset.adding;
      selectors.forEach(select => { select.disabled = false; });
      button.removeAttribute('aria-busy');
      const id = String(new FormData(form).get('id') || '');
      const data = form.querySelector('[data-variant-data], [data-product-variants]') || form.closest('[data-main-product]')?.querySelector('[data-product-variants]');
      button.disabled = data ? !JSON.parse(data.dataset.variants).find(variant => String(variant.id) === id)?.available : false;
    }
  }

  document.addEventListener('click', event => {
    const link = event.target.closest('[data-quick-view]');
    if (!link || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    openQuickView(link);
  });
  document.addEventListener('change', event => {
    const form = event.target.closest('[data-variant-form]');
    if (form && event.target.closest('[data-variant-option]')) updateVariant(form);
    const cardForm = event.target.closest('[data-product-card] form');
    if (cardForm && event.target.matches('input[name="id"]')) updateCard(cardForm);
  });
  document.addEventListener('submit', event => {
    const form = event.target.closest('[data-catalog-add-form]');
    if (!form) return;
    event.preventDefault();
    addToBag(form);
  });
  function initCards(scope = document) { scope.querySelectorAll('[data-product-card] form').forEach(updateCard); }
  document.addEventListener('DOMContentLoaded', () => { initCollections();initCards(); });
  document.addEventListener('catalog:cards:load', event => initCards(event.detail.root));
  document.addEventListener('shopify:section:load', event => { initCollections(event.target);initCards(event.target); });
  document.addEventListener('shopify:section:unload', event => {
    event.target.querySelectorAll('[data-collection-section]').forEach(section => {
      collections.get(section)?.(); collections.delete(section); initialized.delete(section);
    });
    if (quickTrigger && event.target.contains(quickTrigger)) { quickRequest?.abort(); quickDialog()?.close(); quickTrigger = null; }
    window.AtelierTheme.syncScrollLock();
  });
})();

/* Native disclosures and dialogs, plus progressively enhanced Shopify search. */
(() => {
  'use strict';
  const components = new WeakMap();

  function initHeader(root) {
    if (components.has(root)) return;
    const lifecycle = new AbortController();
    const { signal } = lifecycle;
    components.set(root, lifecycle);
    root.classList.add('header-enhanced');
    const header = root.querySelector('[data-header]');
    const menu = root.querySelector('[data-mobile-nav-drawer]');
    const search = root.querySelector('[data-header-search-dialog]');
    const toggle = root.querySelector('[data-mobile-menu-toggle]');
    const transparent = header.classList.contains('is-transparent');
    const updateHeader = (initial = false) => {
      const scrolled = initial === true ? false : window.scrollY > 40;
      header.classList.toggle('is-scrolled', scrolled);
      header.classList.toggle('is-transparent', transparent && !scrolled && !menu.open && !search.open);
    };
    window.addEventListener('scroll', updateHeader, { passive: true, signal });
    updateHeader(true);
    const openDialog = (dialog, trigger) => {
      [menu, search].forEach(other => { if (other !== dialog && other.open) other.close(); });
      dialog.returnTrigger = trigger;
      dialog.showModal();
      document.body.style.overflow = 'hidden';
      toggle.setAttribute('aria-expanded', String(menu.open));
      updateHeader();
      if (dialog === search) dialog.querySelector('input[type="search"]')?.focus();
    };
    [menu, search].forEach(dialog => {
      dialog.addEventListener('click', event => {
        const bounds = dialog.getBoundingClientRect();
        const backdrop = event.target === dialog && (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom);
        if (event.target.closest('[data-header-dialog-close]') || backdrop) dialog.close();
      }, { signal });
      dialog.addEventListener('close', () => {
        const anotherOpen = menu.open || search.open;
        document.body.style.overflow = document.querySelector('dialog[open], [data-cart-drawer].is-open') ? 'hidden' : '';
        toggle.setAttribute('aria-expanded', String(menu.open));
        updateHeader();
        if (!anotherOpen && !document.querySelector('[data-cart-drawer].is-open')) dialog.returnTrigger?.focus();
        if (dialog === search) dialog.dispatchEvent(new Event('search:reset'));
      }, { signal });
    });
    toggle.addEventListener('click', () => openDialog(menu, toggle), { signal });
    root.querySelector('[data-header-search-open]').addEventListener('click', event => {
      event.preventDefault();
      openDialog(search, event.currentTarget);
    }, { signal });
    menu.addEventListener('click', event => { if (event.target.closest('a')) menu.close(); }, { signal });
    const disclosures = [...root.querySelectorAll('.header-menu--desktop details')];
    const closeTimers = new Map();
    const cancelClose = details => { clearTimeout(closeTimers.get(details)); closeTimers.delete(details); };
    const closeMenus = () => disclosures.forEach(details => { cancelClose(details); details.open = false; });
    disclosures.forEach(details => {
      details.addEventListener('pointerenter', event => {
        if (event.pointerType !== 'mouse' || window.innerWidth < 1025) return;
        cancelClose(details);
        disclosures.forEach(other => { if (other !== details) { cancelClose(other); other.open = false; } });
        details.open = true;
      }, { signal });
      details.addEventListener('pointerleave', event => {
        if (event.pointerType !== 'mouse') return;
        cancelClose(details);
        closeTimers.set(details, setTimeout(() => {
          closeTimers.delete(details);
          if (!details.contains(document.activeElement)) details.open = false;
        }, 180));
      }, { signal });
      details.addEventListener('focusin', () => cancelClose(details), { signal });
      details.addEventListener('focusout', event => {
        if (!details.contains(event.relatedTarget)) { cancelClose(details); details.open = false; }
      }, { signal });
    });
    lifecycle.signal.addEventListener('abort', closeMenus, { once: true });
    disclosures.forEach(details => details.addEventListener('toggle', () => {
      if (details.open) disclosures.forEach(other => { if (other !== details) other.open = false; });
    }, { signal }));
    document.addEventListener('click', event => {
      if (!event.target.closest('.header-menu--desktop')) closeMenus();
    }, { signal });
    root.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || event.defaultPrevented) return;
      const open = [menu, search].find(dialog => dialog.open);
      if (open) { event.preventDefault(); open.close(); return; }
      const details = event.target.closest('.header-menu--desktop details[open]');
      if (details) { details.open = false; details.querySelector('summary').focus(); }
    }, { signal });
    const desktop = window.matchMedia('(min-width: 1025px)');
    desktop.addEventListener('change', () => { closeMenus(); if (desktop.matches && menu.open) menu.close(); }, { signal });
  }

  function initSearch(root) {
    if (components.has(root)) return;
    const lifecycle = new AbortController();
    const { signal } = lifecycle;
    components.set(root, lifecycle);
    const input = root.querySelector('[data-search-input]');
    const results = root.querySelector('[data-search-results]');
    const status = root.querySelector('[data-search-status]');
    const form = root.querySelector('form');
    const endpoint = root.dataset.predictiveUrl;
    if (!endpoint) return;
    input.setAttribute('role', 'combobox');
    input.setAttribute('aria-autocomplete', 'list');
    input.setAttribute('aria-controls', results.id);
    input.setAttribute('aria-expanded', 'false');
    input.setAttribute('autocomplete', 'off');
    let timer;
    let request;
    let version = 0;
    let activeIndex = -1;
    const options = () => [...results.querySelectorAll('[role="option"]')];
    const activate = index => {
      const items = options();
      activeIndex = index;
      items.forEach((item, i) => item.setAttribute('aria-selected', String(i === index)));
      if (index >= 0 && items[index]) {
        input.setAttribute('aria-activedescendant', items[index].id);
        items[index].scrollIntoView({ block: 'nearest' });
      } else input.removeAttribute('aria-activedescendant');
    };
    const reset = () => {
      clearTimeout(timer);
      timer = null;
      request?.abort();
      version += 1;
      activeIndex = -1;
      results.replaceChildren();
      results.hidden = true;
      status.textContent = '';
      input.removeAttribute('aria-activedescendant');
      input.removeAttribute('aria-busy');
      input.setAttribute('aria-expanded', 'false');
    };
    lifecycle.signal.addEventListener('abort', reset, { once: true });
    root.closest('dialog')?.addEventListener('search:reset', reset, { signal });
    async function suggest(term, expectedVersion) {
      timer = null;
      request = new AbortController();
      const current = request;
      input.setAttribute('aria-busy', 'true');
      status.textContent = 'Searching…';
      try {
        const url = new URL(endpoint, window.location.origin);
        url.searchParams.set('q', term);
        url.searchParams.set('resources[type]', 'product,page');
        url.searchParams.set('resources[limit]', '6');
        url.searchParams.set('resources[limit_scope]', 'all');
        url.searchParams.set('section_id', 'predictive-search');
        const response = await fetch(url, { signal: current.signal, headers: { Accept: 'text/html' } });
        if (!response.ok) throw new Error('Suggestions are unavailable.');
        const html = await response.text();
        if (current.signal.aborted || expectedVersion !== version) return;
        const parsed = new DOMParser().parseFromString(html, 'text/html');
        const content = parsed.querySelector('[data-predictive-results]');
        if (!content) throw new Error('Suggestions are unavailable.');
        results.replaceChildren(...content.childNodes);
        const items = options();
        items.forEach((item, index) => { item.id = `${input.id}-option-${index}`; });
        results.hidden = items.length === 0;
        input.setAttribute('aria-expanded', String(!results.hidden));
        const count = items.filter(item => !item.classList.contains('predictive-option--all')).length;
        status.textContent = count ? `${count} suggestions. Use the up and down arrow keys to explore.` : 'No suggestions. Press Enter to search all results.';
      } catch (error) {
        if (current.signal.aborted || expectedVersion !== version) return;
        results.hidden = true;
        input.setAttribute('aria-expanded', 'false');
        status.textContent = 'Suggestions are unavailable. Press Enter or use Search to see all results.';
      } finally {
        if (expectedVersion === version) input.removeAttribute('aria-busy');
      }
    }
    input.addEventListener('input', () => {
      reset();
      const term = input.value.trim();
      if (!term || input.isComposing) return;
      const expectedVersion = version;
      timer = setTimeout(() => suggest(term, expectedVersion), 200);
    }, { signal });
    input.addEventListener('compositionend', () => input.dispatchEvent(new Event('input')), { signal });
    input.addEventListener('keydown', event => {
      if (event.isComposing) return;
      if (event.key === 'Escape' && (!results.hidden || timer || input.hasAttribute('aria-busy'))) {
        event.preventDefault();
        event.stopPropagation();
        reset();
      } else if (!results.hidden && ['ArrowDown', 'ArrowUp'].includes(event.key)) {
        event.preventDefault();
        const count = options().length;
        activate(event.key === 'ArrowDown' ? (activeIndex + 1) % count : (activeIndex <= 0 ? count : activeIndex) - 1);
      } else if (event.key === 'Enter' && activeIndex >= 0 && !results.hidden) {
        event.preventDefault();
        options()[activeIndex]?.click();
      } else if (event.key === 'Tab') reset();
    }, { signal });
    results.addEventListener('pointermove', event => {
      const option = event.target.closest('[role="option"]');
      if (option) activate(options().indexOf(option));
    }, { signal });
    // Keep clicked options available until the click fires; collapse when leaving the component.
    document.addEventListener('click', event => { if (!root.contains(event.target)) reset(); }, { signal });
    form.addEventListener('submit', reset, { signal });
  }

  function init(scope = document) {
    scope.querySelectorAll('[data-header-section]').forEach(initHeader);
    scope.querySelectorAll('[data-predictive-search]').forEach(initSearch);
  }
  document.addEventListener('DOMContentLoaded', () => init());
  document.addEventListener('shopify:section:load', event => init(event.target));
  document.addEventListener('shopify:section:unload', event => {
    event.target.querySelectorAll('[data-header-section], [data-predictive-search]').forEach(root => {
      const openDialogs = [...root.querySelectorAll('dialog[open]')];
      openDialogs.forEach(dialog => dialog.close());
      if (openDialogs.length && !document.querySelector('dialog[open], [data-cart-drawer].is-open')) document.body.style.overflow = '';
      components.get(root)?.abort();
      components.delete(root);
    });
  });
  document.addEventListener('click', event => {
    const trigger = event.target.closest('[data-cart-drawer-trigger]');
    if (!trigger || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || !document.querySelector('[data-cart-drawer]')) return;
    event.preventDefault();
    document.querySelectorAll('[data-header-section] dialog[open]').forEach(dialog => dialog.close());
    window.dispatchEvent(new CustomEvent('cart:open'));
  });
})();

