  top: 1rem;
  right: 1rem;
  background: var(--color-bg);
  border-radius: 50%;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.zoom-modal__img {
  max-width: 90vw;
  max-height: 90vh;
  object-fit: contain;
}

@media (max-width: 900px) {
  .product-spotlight__grid {
    grid-template-columns: 1fr;
  }
  .product-spotlight__buy-box-col {
    position: static;
  }
}

/* --------------------------------------------------------------------------
   Section: Why This Bag
   -------------------------------------------------------------------------- */
.section-header {
  margin-bottom: clamp(2.5rem, 5vw, 4.5rem);
}

.section-heading {
  font-size: var(--font-h2);
  margin-top: 0.5rem;
  margin-bottom: 0.75rem;
}

.why-this-bag__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(1.5rem, 3vw, 2.5rem);
}

.why-this-bag__card {
  display: flex;
  flex-direction: column;
}

.why-this-bag__media {
  aspect-ratio: 4/5;
  background-color: var(--color-surface);
  margin-bottom: 1.5rem;
  overflow: hidden;
}

.why-this-bag__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

.why-this-bag__card:hover .why-this-bag__image {
  transform: scale(1.03);
}

.why-this-bag__placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
}

.why-this-bag__title {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.why-this-bag__text {
  font-size: 0.9375rem;
  line-height: 1.6;
}

@media (max-width: 1024px) {
  .why-this-bag__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .why-this-bag__grid {
    grid-template-columns: 1fr;
  }
}

/* --------------------------------------------------------------------------
   Section: Detail Close-ups
   -------------------------------------------------------------------------- */
.detail-closeups__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1.5rem, 3vw, 3rem);
}

.detail-closeups__media {
  aspect-ratio: 1/1;
  background-color: var(--color-surface);
  margin-bottom: 1.25rem;
  overflow: hidden;
}

.detail-closeups__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

.detail-closeups__card:hover .detail-closeups__image {
  transform: scale(1.03);
}

.detail-closeups__placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
}

.detail-closeups__title {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

@media (max-width: 768px) {
  .detail-closeups__grid {
    grid-template-columns: 1fr;
  }
}

/* --------------------------------------------------------------------------
   Section: What Fits & Dimensions
   -------------------------------------------------------------------------- */
.what-fits__grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: clamp(2rem, 5vw, 4.5rem);
  align-items: center;
}

.what-fits__media-wrap {
  aspect-ratio: 4/3;
  background-color: var(--color-surface);
  overflow: hidden;
  margin-bottom: 1.5rem;
}

.what-fits__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.what-fits__placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.what-fits__items-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.625rem;
}

.what-fits__pill {
  display: inline-flex;
  padding: 0.375rem 0.875rem;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  font-size: 0.8125rem;
  color: var(--color-ink);
  letter-spacing: 0.02em;
}

.dimensions-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  padding: clamp(2rem, 4vw, 3rem);
}

.dimensions-card__title {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.dimensions-table {
  width: 100%;
  border-collapse: collapse;
}

.dimensions-table th, .dimensions-table td {
  padding: 0.875rem 0;
  border-bottom: 1px solid rgba(217, 208, 195, 0.6);
  font-size: 0.9375rem;
  text-align: left;
}

.dimensions-table th {
  font-weight: 600;
  color: var(--color-ink);
  width: 45%;
}

.dimensions-table td {
  color: var(--color-ink);
}

@media (max-width: 900px) {
  .what-fits__grid {
    grid-template-columns: 1fr;
  }
}

/* --------------------------------------------------------------------------
   Section: Color Story
   -------------------------------------------------------------------------- */
.color-story__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(1.5rem, 3vw, 2.5rem);
}

.color-story__media {
  aspect-ratio: 4/5;
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid var(--color-border);
}

.color-story__swatch-circle {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.15);
}

.color-story__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.color-story__name {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.color-story__desc {
  font-size: 0.875rem;
  line-height: 1.5;
}

@media (max-width: 1024px) {
  .color-story__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .color-story__grid {
    grid-template-columns: 1fr;
  }
}

/* --------------------------------------------------------------------------
   Section: Product Reviews
   -------------------------------------------------------------------------- */
.reviews__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.review-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  padding: 2.25rem;
  display: flex;
  flex-direction: column;
}

.review-card__stars {
  color: var(--color-accent);
  letter-spacing: 0.15em;
  margin-bottom: 1.25rem;
  font-size: 1.125rem;
}

.review-card__quote {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  line-height: 1.4;
  color: var(--color-ink);
  margin-bottom: 1.5rem;
  flex-grow: 1;
}

.review-card__author {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  font-size: 0.8125rem;
}

/* --------------------------------------------------------------------------
   Section: Comparison Table
   -------------------------------------------------------------------------- */
.comparison-table-wrap {
  max-width: 960px;
  margin: 0 auto;
  overflow-x: auto;
}

.comparison-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
}

.comparison-table th, .comparison-table td {
  padding: 1.25rem 1.5rem;
  border: 1px solid var(--color-border);
  vertical-align: middle;
}

.comparison-table thead th {
  background-color: var(--color-bg);
  font-size: 0.9375rem;
}

.comparison-table__brand-col {
