  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.comparison-table td.is-highlight {
  background-color: #FAF8F4;
}

/* --------------------------------------------------------------------------
   Section: FAQ
   -------------------------------------------------------------------------- */
.container--narrow {
  max-width: 800px;
}

/* --------------------------------------------------------------------------
   Section: Brand Story
   -------------------------------------------------------------------------- */
.brand-story__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(2.5rem, 6vw, 6rem);
  align-items: center;
}

.brand-story__media {
  aspect-ratio: 4/5;
  background-color: var(--color-surface);
  overflow: hidden;
}

.brand-story__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.brand-story__placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-muted);
}

.brand-story__heading {
  font-size: var(--font-h2);
  margin-top: 0.5rem;
  margin-bottom: 1.5rem;
}

.brand-story__body p {
