}

.sticky-cart-bar.is-visible {
  transform: translateY(0);
}

.sticky-cart-bar__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
  gap: 1.5rem;
}

.sticky-cart-bar__product-info {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.sticky-cart-bar__thumb {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: var(--color-surface);
  flex-shrink: 0;
}

.sticky-cart-bar__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sticky-cart-bar__placeholder-thumb {
  width: 100%;
  height: 100%;
  background-color: var(--color-surface);
}

.sticky-cart-bar__title {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-ink);
  line-height: 1.2;
}

.sticky-cart-bar__sub {
  font-size: 0.8125rem;
  color: var(--color-muted);
  display: flex;
  gap: 0.375rem;
  align-items: center;
}

.sticky-cart-bar__btn {
  min-height: 44px;
  padding: 0.5rem 1.75rem;
  font-size: 0.75rem;
}

@media (max-width: 600px) {
